{"code":"await Bun.write("src/cli.rs", `pub struct CliConfig {
    pub output: String,
    pub verbose: bool,
}

impl CliConfig {
    pub fn new() -> Self {
        Self {
            output: String::from("default"),
            verbose: false,
        }
    }

    /// Builds a config from command-line arguments (program name excluded).
    /// Recognizes \`--verbose\`; any other argument is an error.
    pub fn from_args<I, S>(args: I) -> Result<Self, String>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut config = Self::new();
        for arg in args {
            match arg.as_ref() {
                "--verbose" => config.verbose = true,
                other => return Err(format!("unknown argument: {other}")),
            }
        }
        Ok(config)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cli_config() {
        let config = CliConfig::new();
        assert_eq!(config.output, "default");
        assert!(!config.verbose);
    }

    #[test]
    fn from_args_without_flag_is_not_verbose() {
        let config = CliConfig::from_args(Vec::<String>::new()).unwrap();
        assert!(!config.verbose);
    }

    #[test]
    fn from_args_parses_verbose() {
        let config = CliConfig::from_args(["--verbose"]).unwrap();
        assert!(config.verbose);
    }

    #[test]
    fn from_args_rejects_unknown_argument() {
        assert!(CliConfig::from_args(["--nope"]).is_err());
    }
}
